import Database from 'better-sqlite3';

const DB_PATH = '/home/user/qwik-app/db.sqlite';

const db = new Database(DB_PATH);

// Enable WAL mode for concurrent requests and to avoid database locking issues
db.pragma('journal_mode = WAL');

// Initialize database schema
db.exec(`
  CREATE TABLE IF NOT EXISTS api_keys (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    key_prefix TEXT NOT NULL,
    hashed_key TEXT NOT NULL,
    status TEXT NOT NULL,
    created_at TEXT NOT NULL
  )
`);

export default db;
export { DB_PATH };

import crypto from 'crypto';

export function generateApiKey(): string {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
  let randomPart = '';
  // crypto.randomBytes is secure and available in Node.js
  const randomBytes = crypto.randomBytes(32);
  for (let i = 0; i < 32; i++) {
    randomPart += chars[randomBytes[i] % chars.length];
  }
  return `qk_${randomPart}`;
}

export function hashKey(key: string): string {
  return crypto.createHash('sha256').update(key).digest('hex');
}

import type { RequestHandler } from '@builder.io/qwik-city';
import db from '../../../../../lib/db';
import { generateApiKey, hashKey } from '../../../../../lib/keys';

export const onPost: RequestHandler = async (event) => {
  try {
    const body = await event.parseBody() as any;
    if (!body || typeof body !== 'object') {
      return event.json(400, { error: 'Invalid request body' });
    }

    const { name } = body;
    if (!name || typeof name !== 'string' || name.trim() === '') {
      return event.json(400, { error: 'Name is required and must be a non-empty string' });
    }

    const trimmedName = name.trim();
    const plainTextKey = generateApiKey();
    const prefix = plainTextKey.substring(0, 7);
    const hashed = hashKey(plainTextKey);
    const status = 'active';
    const createdAt = new Date().toISOString();

    const stmt = db.prepare(`
      INSERT INTO api_keys (name, key_prefix, hashed_key, status, created_at)
      VALUES (?, ?, ?, ?, ?)
    `);

    const result = stmt.run(trimmedName, prefix, hashed, status, createdAt);
    const id = Number(result.lastInsertRowid);

    return event.json(201, {
      id,
      name: trimmedName,
      prefix,
      key: plainTextKey,
      status,
      created_at: createdAt
    });
  } catch (err: any) {
    console.error('Error in POST /api/v1/developer/keys:', err);
    return event.json(500, { error: 'Internal server error' });
  }
};

export const onGet: RequestHandler = async (event) => {
  try {
    const stmt = db.prepare(`
      SELECT id, name, key_prefix AS prefix, status, created_at
      FROM api_keys
      ORDER BY id DESC
    `);
    const keys = stmt.all();
    return event.json(200, keys);
  } catch (err: any) {
    console.error('Error in GET /api/v1/developer/keys:', err);
    return event.json(500, { error: 'Internal server error' });
  }
};

import type { RequestHandler } from '@builder.io/qwik-city';
import db from '../../../../../../lib/db';

export const onPost: RequestHandler = async (event) => {
  try {
    const { id } = event.params;
    const keyId = Number(id);

    if (isNaN(keyId)) {
      return event.json(400, { error: 'Invalid key ID' });
    }

    // Check if the key exists
    const keyExists = db.prepare('SELECT id FROM api_keys WHERE id = ?').get(keyId);
    if (!keyExists) {
      return event.json(404, { error: 'Key not found' });
    }

    // Update status to 'revoked'
    db.prepare("UPDATE api_keys SET status = 'revoked' WHERE id = ?").run(keyId);

    return event.json(200, {
      success: true,
      message: 'API key has been successfully revoked'
    });
  } catch (err: any) {
    console.error('Error in POST /api/v1/developer/keys/:id/revoke:', err);
    return event.json(500, { error: 'Internal server error' });
  }
};

import type { RequestHandler } from '@builder.io/qwik-city';
import db from '../../../../lib/db';
import { hashKey } from '../../../../lib/keys';

export const onGet: RequestHandler = async (event) => {
  try {
    const apiKey = event.request.headers.get('x-api-key');
    if (!apiKey) {
      return event.json(401, { error: 'Unauthorized' });
    }

    const hashed = hashKey(apiKey);
    const keyRecord = db.prepare(`
      SELECT status FROM api_keys WHERE hashed_key = ?
    `).get(hashed) as { status: string } | undefined;

    if (!keyRecord || keyRecord.status !== 'active') {
      return event.json(401, { error: 'Unauthorized' });
    }

    return event.json(200, {
      message: 'Hello, authenticated developer!'
    });
  } catch (err: any) {
    console.error('Error in GET /api/v1/hello:', err);
    return event.json(500, { error: 'Internal server error' });
  }
};

